import assert from 'node:assert/strict';
import { execFileSync, spawn, spawnSync } from 'node:child_process';
import { cp, lstat, mkdir, mkdtemp, readFile, readlink, rm, stat, writeFile } from 'node:fs/promises';
import net from 'node:net';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { DatabaseSync } from 'node:sqlite';
import { Store } from '../src/store.js';

const archive = 'release/viqueue-v0.4.1-rc.tar.gz';
async function port(){const s=net.createServer();await new Promise(r=>s.listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise(r=>s.close(r));return p}
async function extract(){const work=await mkdtemp(path.join(tmpdir(),'viq-bundle-'));execFileSync('tar',['-xzf',path.resolve(archive),'-C',work]);return{work,bundle:path.join(work,'viqueue-v0.4.1-rc')}}
function install(bundle,prefix,extra={}){return spawnSync('bash',[path.join(bundle,'install-local.sh')],{cwd:bundle,encoding:'utf8',env:{...process.env,VIQ_PREFIX:prefix,...extra}})}
function walInsert(storage,key){const code="import{DatabaseSync}from'node:sqlite';const d=new DatabaseSync(process.argv[1]);d.exec('PRAGMA journal_mode=WAL; PRAGMA wal_autocheckpoint=0');d.prepare('INSERT INTO projects(key,next_number,created_at) VALUES(?,1,?)').run(process.argv[2],Date.now());process.exit(0)";const r=spawnSync(process.execPath,['--input-type=module','-e',code,storage,key],{encoding:'utf8'});assert.equal(r.status,0,r.stderr)}
function hasProject(storage,key){const db=new DatabaseSync(storage,{readOnly:true});const row=db.prepare('SELECT 1 ok FROM projects WHERE key=?').get(key);db.close();return Boolean(row)}

const linuxOnly = process.platform === 'darwin' ? 'requires Linux deployment tooling (GNU coreutils)' : false;
test.before(()=>{if(linuxOnly)return;execFileSync('npm',['run','bundle'],{stdio:'pipe'});execFileSync('sha256sum',['-c',`${path.basename(archive)}.sha256`],{cwd:'release',stdio:'pipe'})});

test('local bundle installs read-only MCP and performs WAL-consistent fail-closed rollback',{skip:linuxOnly},async t=>{const{work,bundle}=await extract();assert.equal((await readFile(path.join(bundle,'SOURCE_COMMIT'),'utf8')).trim(),execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim());assert.equal(await stat(path.join(bundle,'sqlite-backup.js')).then(s=>s.isFile()),true);for(const required of ['bin/viq-recover-coordinator.js','src/local-coordinator-recovery.js','src/operator-cli.js','src/operator-server.js'])assert.equal((await stat(path.join(bundle,required))).isFile(),true);for(const forbidden of['src/phone-auth-store.js','src/phone-gateway.js','bin/viq-phone-auth.js'])await assert.rejects(stat(path.join(bundle,forbidden)));const prefix=path.join(work,'prefix');assert.equal(install(bundle,prefix).status,0);const recovery=path.join(prefix,'bin','viq-recover-coordinator');assert.equal((await lstat(recovery)).isSymbolicLink(),true);const recoveryHelp=spawnSync(recovery,[],{encoding:'utf8'});assert.equal(recoveryHelp.status,2,recoveryHelp.stderr);assert.doesNotMatch(recoveryHelp.stderr,/ERR_MODULE_NOT_FOUND/);const storage=path.join(work,'data','viqueue.sqlite');const bootstrap=JSON.parse(execFileSync(path.join(prefix,'bin','viq-bootstrap'),['--storage',storage,'--id','coord','--name','Coordinator'],{encoding:'utf8'}));const listen=await port(),operatorSocket=path.join(work,'operator.sock'),server=spawn(path.join(prefix,'bin','viqueue-server'),[`--port=${listen}`,`--storage=${storage}`,`--operator-socket=${operatorSocket}`]);t.after(()=>server.kill());const base=`http://127.0.0.1:${listen}`;for(let i=0;i<100;i++){try{if((await fetch(`${base}/health`)).ok)break}catch{}await new Promise(r=>setTimeout(r,10))}let sessionCapability;const viq=(token,...a)=>spawnSync(path.join(prefix,'bin','viq'),[...a,'--server',base,'--device-token',token],{encoding:'utf8',env:{...process.env,...(sessionCapability?{VIQ_SESSION_CAPABILITY:sessionCapability}:{})}});assert.equal(viq(bootstrap.credential,'project','create','ABC').status,0);const handoff=path.join(work,'installed-handoff.json'),operatorStarted=Date.now(),operatorModule=path.join(prefix,'lib/viqueue/current/src/operator-cli.js'),operatorCode=`import{runOperatorCommand}from ${JSON.stringify('file://'+operatorModule)};await runOperatorCommand(['pairing','create','--kind','browser','--name','Installed Browser','--output',process.argv[1]],{socketPath:process.argv[2]})`,operatorRun=spawnSync(process.execPath,['--input-type=module','-e',operatorCode,handoff,operatorSocket],{encoding:'utf8',env:{...process.env}});assert.equal(operatorRun.status,0,operatorRun.stderr);const installedHandoff=JSON.parse(await readFile(handoff,'utf8'));assert.deepEqual(Object.keys(installedHandoff).sort(),['code','device_id','device_name','expires_at']);assert.ok(installedHandoff.expires_at>=operatorStarted+3600000&&installedHandoff.expires_at<=Date.now()+3600000);assert.equal((await stat(handoff)).mode&0o777,0o600);const pc=JSON.parse(viq(bootstrap.credential,'device','pair-code','--kind','worker','--actor','coord','--id','worker','--name','Worker').stdout),paired=await(await fetch(`${base}/v1/devices/pair`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:pc.code})})).json();assert.equal(viq(bootstrap.credential,'ticket','create','ABC','installed','--assignment','Agent').status,0);sessionCapability=(await(await fetch(`${base}/v1/sessions`,{method:'POST',headers:{authorization:`Bearer ${paired.credential}`,'content-type':'application/json'},body:'{}'})).json()).session_capability;assert.equal(JSON.parse(viq(paired.credential,'ticket','claim','ABC-1').stdout).ticket.id,'ABC-1');const mcp=spawnSync(path.join(prefix,'bin','viq-mcp'),[],{encoding:'utf8',env:{...process.env,VIQ_URL:base,VIQ_DEVICE_TOKEN:paired.credential},input:'{"jsonrpc":"2.0","id":1,"method":"tools/list","params":{}}\n'});const names=JSON.parse(mcp.stdout).result.tools.map(x=>x.name);assert.ok(names.includes('ticket_next'));assert.equal(names.some(name=>name.includes('claim')||name==='event_post'||name==='ticket_submit'),false);server.kill();walInsert(storage,'WALPRIOR');assert.equal(hasProject(storage,'WALPRIOR'),true);const second=path.join(work,'second-release');await cp(bundle,second,{recursive:true});await writeFile(path.join(second,'SOURCE_COMMIT'),`${'b'.repeat(40)}\n`);assert.equal(install(second,prefix,{VIQ_STORAGE:storage,VIQ_SNAPSHOT_CONFIRMED_OFFLINE:'1'}).status,0);assert.match(await readlink(path.join(prefix,'lib/viqueue/current')),/b{40}$/);walInsert(storage,'CANDIDATE');assert.equal(hasProject(storage,'CANDIDATE'),true);const preserve=`${storage}.pre-rollback`;await mkdir(preserve);const rollbackEnv={...process.env,VIQ_PREFIX:prefix,VIQ_STORAGE:storage,VIQ_RESTORE_STORAGE:'1',VIQ_SNAPSHOT_CONFIRMED_OFFLINE:'1'};assert.notEqual(spawnSync('bash',[path.join(second,'rollback-local.sh')],{env:rollbackEnv}).status,0);assert.equal(hasProject(storage,'CANDIDATE'),true);assert.match(await readlink(path.join(prefix,'lib/viqueue/current')),/b{40}$/);await rm(preserve,{recursive:true});execFileSync('bash',[path.join(second,'rollback-local.sh')],{env:rollbackEnv});await assert.rejects(stat(`${storage}-wal`));await assert.rejects(stat(`${storage}-shm`));assert.equal(hasProject(storage,'WALPRIOR'),true);assert.equal(hasProject(storage,'CANDIDATE'),false);assert.equal(hasProject(`${storage}.pre-rollback`,'CANDIDATE'),true);assert.match(await readlink(path.join(prefix,'lib/viqueue/current')),new RegExp(`${(await readFile(path.join(bundle,'SOURCE_COMMIT'),'utf8')).trim()}$`));execFileSync('bash',[path.join(bundle,'uninstall-local.sh')],{env:{...process.env,VIQ_PREFIX:prefix}});assert.equal(spawnSync(path.join(prefix,'bin','viq')).error?.code,'ENOENT');assert.equal(hasProject(storage,'WALPRIOR'),true)});

test('failed database validation cleans staged immutable release for retry',{skip:linuxOnly},async()=>{const{work,bundle}=await extract(),prefix=path.join(work,'prefix'),storage=path.join(work,'invalid.sqlite'),release=path.join(prefix,'lib/viqueue/releases',`${'c'.repeat(40)}`);await writeFile(path.join(bundle,'SOURCE_COMMIT'),`${'c'.repeat(40)}\n`);await writeFile(storage,'not sqlite');assert.notEqual(install(bundle,prefix,{VIQ_STORAGE:storage,VIQ_SNAPSHOT_CONFIRMED_OFFLINE:'1'}).status,0);await assert.rejects(stat(release));await rm(storage);const store=new Store(storage);await store.init();await store.close();assert.equal(install(bundle,prefix,{VIQ_STORAGE:storage,VIQ_SNAPSHOT_CONFIRMED_OFFLINE:'1'}).status,0);assert.equal((await stat(release)).isDirectory(),true)});
